import React from 'react';
import { View, Text } from 'react-native';

import { SearchNumber } from '../../components/SearchNumber';
import { styles } from './styles';

export function SearchBar() {
    return (
        <View style={styles.container}>
            <View style={[styles.containerButton, { backgroundColor: '#fff' }]}>
                <Text style={{ fontSize: 17, color: '#121212' }}>Livre</Text>
            </View>

            <View style={[styles.containerButton, { backgroundColor: '#17A2B7' }]}>
                <Text style={{ fontSize: 17, color: '#fff', }}>Em análise</Text>
            </View>

            <View style={[styles.containerButton, { backgroundColor: '#26A744' }]}>
                <Text style={{ fontSize: 17, color: '#fff' }}>Pago</Text>
            </View>

            <View style={[styles.containerButton, { backgroundColor: '#26A744' }]}>
                <Text style={{ fontSize: 17, color: '#fff' }}>Pago</Text>
            </View>
        </View>
    );
};
